record.field:
blocages = []
for session in records:
    if session.state in ('opening_control', 'opened'):
        for b in session._laresidence_auto_close_blockers():
            blocages.append("%s : %s" % (session.name, b))
if blocages:
    titre = "La caisse ne peut pas être fermée"
    corps = "\n".join("- " + b for b in blocages)
    genre = "warning"
else:
    titre = "La caisse peut être fermée"
    corps = "Aucune commande ouverte, aucune préparation en attente, aucune activité récente."
    genre = "success"
action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {'title': titre, 'message': corps, 'type': genre, 'sticky': True},
}
